27	const (
28		// status is the path to the status field in the metadata
29		status       = "attributes.status.details"
30		healthPolicy = "attributes.status.healthPolicy"
31		customStatus = "attributes.status.customStatus"
32		// localFieldPrefix is the prefix for local fields not output to the status
33		localFieldPrefix = "$"
34	)
35	
36	// EncodeMetadata encodes native CUE in the metadata fields to a CUE string literal
37	func EncodeMetadata(field *ast.Field) error {
38		if err := marshalField[*ast.StructLit](field, healthPolicy, validateHealthPolicyField); err != nil {
39			return err
40		}
41		if err := marshalField[*ast.StructLit](field, customStatus, validateCustomStatusField); err != nil {
42			return err
43		}
44		if err := marshalField[*ast.StructLit](field, status, validateStatusField); err != nil {
45			return err
46		}
47		return nil
48	}
49	
50	// DecodeMetadata decodes a CUE string literal in the metadata fields to native CUE expressions
51	func DecodeMetadata(field *ast.Field) error {
52		if err := unmarshalField[*ast.StructLit](field, healthPolicy, validateHealthPolicyField); err != nil {
53			return err
54		}
55		if err := unmarshalField[*ast.StructLit](field, customStatus, validateCustomStatusField); err != nil {
56			return err
57		}
58		if err := unmarshalField[*ast.StructLit](field, status, validateStatusField); err != nil {
59			return err
60		}
61		return nil
62	}
63	
64	func marshalField[T ast.Node](field *ast.Field, key string, validator func(T) error) error {
65		if statusField, ok := GetFieldByPath(field, key); ok {
66			switch expr := statusField.Value.(type) {
67			case *ast.BasicLit:
68				if expr.Kind != token.STRING {
69					return fmt.Errorf("expected %s field to be string, got %v", key, expr.Kind)
70				}
71				if err := ValidateCueStringLiteral[T](expr, validator); err != nil {
72					return fmt.Errorf("%s field failed validation: %w", key, err)
73				}
74				return nil
75	
76			case *ast.StructLit:
77				structLit := expr
78				v, ok := ast.Node(structLit).(T)
79				if !ok {
80					return fmt.Errorf("%s field: cannot convert *ast.StructLit to expected type", key)
81				}
82				err := validator(v)
83				if err != nil {
84					return err
85				}
86				strLit, err := StringifyStructLitAsCueString(structLit)
87				if err != nil {
88					return err
89				}
90				UpdateNodeByPath(field, key, strLit)
91				return nil
92	
93			default:
94				return fmt.Errorf("unexpected type for %s field: %T", key, expr)
95			}
96		}
97		return nil
98	}
99	
100	func unmarshalField[T ast.Node](field *ast.Field, key string, validator func(T) error) error {
101		if statusField, ok := GetFieldByPath(field, key); ok {
102			basicLit, ok := statusField.Value.(*ast.BasicLit)
103			if !ok || basicLit.Kind != token.STRING {
104				return fmt.Errorf("%s field is not a string literal", key)
105			}
106	
107			err := ValidateCueStringLiteral[T](basicLit, validator)
108			if err != nil {
109				return fmt.Errorf("%s field failed validation: %w", key, err)
110			}
111	
112			unquoted := strings.TrimSpace(TrimCueRawString(basicLit.Value))
113	
114			structLit, hasImports, hasPackage, parseErr := ParseCueContent(unquoted)
115			if parseErr != nil {
116				return fmt.Errorf("unexpected error re-parsing validated %s string: %w", key, parseErr)
117			}
118	
119			if hasImports || hasPackage {
120				// Keep as string literal to preserve imports/package
121				return nil
122			}
123	
124			statusField.Value = structLit
125		}
126		return nil
127	}
128	
129	func validateStatusField(sl *ast.StructLit) error {
130		for _, elt := range sl.Elts {
131			f, ok := elt.(*ast.Field)
132			if !ok {
133				return fmt.Errorf("status.details contains non-field element")
134			}
135	
136			label := GetFieldLabel(f.Label)
137	
138			if strings.HasPrefix(label, localFieldPrefix) {
139				continue
140			}
141	
142			switch f.Value.(type) {
143			case *ast.BasicLit,
144				*ast.Ident,
145				*ast.SelectorExpr,
146				*ast.CallExpr,
147				*ast.BinaryExpr:
148				continue
149			default:
150				return fmt.Errorf("status.details field %q contains unsupported expression type %T", label, f.Value)
151			}
152		}
153		return nil
154	}
155	
156	func validateCustomStatusField(sl *ast.StructLit) error {
157		validator := func(expr ast.Expr) error {
158			switch v := expr.(type) {
159			case *ast.BasicLit:
160				if v.Kind != token.STRING {
161					return fmt.Errorf("customStatus field 'message' must be a string, got %v", v.Kind)
162				}
163			case *ast.Interpolation, *ast.CallExpr, *ast.SelectorExpr, *ast.Ident, *ast.BinaryExpr, *ast.ParenExpr,
164				*ast.ListLit, *ast.IndexExpr, *ast.SliceExpr, *ast.Comprehension:
165			default:
166				return fmt.Errorf("customStatus field 'message' must be a string expression, got %T", v)
167			}
168			return nil
169		}
170	
171		found, err := FindAndValidateField(sl, "message", validator)
172		if err != nil {
173			return err
174		}
175		if !found {
176			return fmt.Errorf("customStatus must contain a 'message' field")
177		}
178	
179		return nil
180	}
181	
182	func validateHealthPolicyField(sl *ast.StructLit) error {
183		validator := func(expr ast.Expr) error {
184			switch v := expr.(type) {
185			case *ast.Ident:
186			case *ast.BasicLit:
187				if v.Kind != token.TRUE && v.Kind != token.FALSE {
188					return fmt.Errorf("healthPolicy field 'isHealth' must be a boolean literal (true/false), got %v", v.Kind)
189				}
190			case *ast.BinaryExpr, *ast.UnaryExpr, *ast.CallExpr, *ast.SelectorExpr, *ast.ParenExpr:
191			default:
192				return fmt.Errorf("healthPolicy field 'isHealth' must be a boolean expression, got %T", v)
193			}
194			return nil
195		}
196	
197		found, err := FindAndValidateField(sl, "isHealth", validator)
198		if err != nil {
199			return err
200		}
201		if !found {
202			return fmt.Errorf("healthPolicy must contain an 'isHealth' field")
203		}
204	
205		return nil
206	}
