227	// FindAndValidateField searches for a field at the top level or within top-level if statements
228	func FindAndValidateField(sl *ast.StructLit, fieldName string, validator fieldValidator) (found bool, err error) {
229		// First check top-level fields
230		for _, elt := range sl.Elts {
231			if field, ok := elt.(*ast.Field); ok {
232				label := GetFieldLabel(field.Label)
233				if label == fieldName {
234					found = true
235					if validator != nil {
236						err = validator(field.Value)
237					}
238					return found, err
239				}
240			}
241		}
242	
243		// If not found at top level, check within top-level if statements
244		for _, elt := range sl.Elts {
245			if comp, ok := elt.(*ast.Comprehension); ok {
246				// Check if this comprehension has if clauses (conditional fields)
247				hasIfClause := false
248				for _, clause := range comp.Clauses {
249					if _, ok := clause.(*ast.IfClause); ok {
250						hasIfClause = true
251						break
252					}
253				}
254	
255				// If it has an if clause and the value is a struct, search within it
256				if hasIfClause {
257					if structLit, ok := comp.Value.(*ast.StructLit); ok {
258						if innerFound, innerErr := FindAndValidateField(structLit, fieldName, validator); innerFound {
259							return true, innerErr
260						}
261					}
262				}
263			}
264		}
